'use client';

import { Grid } from '@eregister/wit-grid-react';

const rows = [
	{ id: 'row-1', name: 'Ada Lovelace', team: 'Compute', status: 'Active' },
	{ id: 'row-2', name: 'Grace Hopper', team: 'Compiler', status: 'Active' },
	{ id: 'row-3', name: 'Katherine Johnson', team: 'Flight', status: 'Review' },
	{ id: 'row-4', name: 'Dorothy Vaughan', team: 'Systems', status: 'Active' },
];

const columns = [
	{ field: 'name', header: 'Name', width: 180 },
	{ field: 'team', header: 'Team', width: 160 },
	{ field: 'status', header: 'Status', width: 140 },
];

export default function BasicGridExample() {
	return <Grid rows={rows} columns={columns} getRowId={(row) => row.id} showStatusBar />;
}

'use client';

import { Grid } from '@eregister/wit-grid-react';

const rows = Array.from({ length: 24 }, (_, index) => ({
	id: `asset-${index + 1}`,
	symbol: `WG-${String(index + 1).padStart(3, '0')}`,
	latency: `${3 + (index % 5)}ms`,
	region: ['iad', 'bom', 'fra', 'sin'][index % 4],
}));

const columns = [
	{ field: 'symbol', header: 'Symbol', width: 130 },
	{ field: 'region', header: 'Region', width: 120 },
	{ field: 'latency', header: 'Latency', width: 120 },
];

export default function PersistenceExample() {
	return <Grid rows={rows} columns={columns} getRowId={(row) => row.id} persistence='wit-grid-docs-persistence' showStatusBar />;
}

'use client';

import { Grid, type ColumnDef } from '@eregister/wit-grid-react';

type Row = {
	id: string;
	task: string;
	owner: string;
	priority: 'Low' | 'Medium' | 'High';
};

const rows: Row[] = [
	{ id: 'task-1', task: 'Publish migration notes', owner: 'Mira', priority: 'High' },
	{ id: 'task-2', task: 'Audit event payload docs', owner: 'Rey', priority: 'Medium' },
	{ id: 'task-3', task: 'Refresh example coverage', owner: 'Nia', priority: 'Low' },
];

const columns: ColumnDef<Row>[] = [
	{ field: 'task', header: 'Task', width: 240 },
	{ field: 'owner', header: 'Owner', width: 150 },
	{ field: 'priority', header: 'Priority', width: 140 },
];

export default function RowSelectionExample() {
	return <Grid rows={rows} columns={columns} getRowId={(row) => row.id} rowSelection='multiple' showStatusBar />;
}
